{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Spironolactone, the closest structural analogue sharing the steroidal lactone and ketone scaffold, shows near-complete oral bioavailability of its active metabolite canrenone (~98%) in 20 human volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Eplerenone, another spironolactone-type steroidal lactone, has a reported oral bioavailability of ~98% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Hydrocortisone, a less similar steroid, has absolute oral bioavailability of 0.93 (95% CI 0.83-1.05) from a 20 mg tablet in healthy volunteers, corroborating that this steroid class can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Cortisone, another corticosteroid, shows ~85% oral bioavailability in humans, further supporting high F for structurally related steroids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Medroxyprogesterone acetate, a progestin with lower structural similarity, has oral bioavailability probably <15%, but it lacks the spironolactone-like lactone/cyclopropane motif and is heavily first-pass metabolized, so this contradictory evidence carries less weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest structural analogues (spironolactone, eplerenone) with the same steroidal lactone scaffold show near-complete oral bioavailability in humans, and other corticosteroids also show high F. The low-F progestin/steroid evidence is less transferable because those molecules lack the lactone/cyclopropane motif and undergo extensive first-pass metabolism. Therefore the query is predicted high (F >= 20%).",
  "evidence_gaps": [
    "No direct drospirenone-specific bioavailability record is present; prediction relies on close analogues.",
    "Contradictory low-F steroids are structurally more distant and do not share the spironolactone-like lactone/cyclopropane system."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

